SELECT "t11"."order_number", "t11"."line_no", "t11"."item", "t11"."quantity", "t11"."on_hand", "t11"."outage", "t11"."short", 'hold_sales' AS "route", 'shortfall' AS "context"
FROM (SELECT "order_number", "line_no", "item", "quantity", "on_hand", "outage", "quantity" - "on_hand" AS "short"
        FROM (SELECT "t7"."order_number", "t7"."customer", "t7"."channel", "t7"."fulfilling_warehouse", "t7"."value", "t7"."placed_date", "t7"."state", "t7"."line_no", "t7"."item", "t7"."quantity", "t7"."unit_price", "t7"."ext_sales_price", "t7"."warehouse", "t7"."sold_date", "t7"."customer0", "t7"."channel0", "t7"."as_of_date", "t7"."quantity_on_hand", "t7"."_ttrp_g_n8_0", "t7"."_ttrp_g_n8_1", "t7"."_ttrp_d_n8", "t8"."warehouse" AS "warehouse0", "t8"."from_date", "t8"."to_date", "t8"."reason", COALESCE("t7"."quantity_on_hand", 0) AS "on_hand", "t8"."warehouse" IS NOT NULL AS "outage"
                FROM (SELECT "t1"."order_number", "t1"."customer", "t1"."channel", "t1"."fulfilling_warehouse", "t1"."value", "t1"."placed_date", "t1"."state", "t1"."line_no", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."ext_sales_price", "t1"."warehouse", "t1"."sold_date", "t1"."customer0", "t1"."channel0", "t6"."as_of_date", "t6"."quantity_on_hand", "t6"."_ttrp_g_n8_0", "t6"."_ttrp_g_n8_1", "t6"."_ttrp_d_n8"
                        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t0"
                                    INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                            LEFT JOIN (SELECT "t2"."as_of_date", "t2"."item", "t2"."warehouse", "t2"."quantity_on_hand", "t2"."_ttrp_g_n8_0", "t2"."_ttrp_g_n8_1", "t2"."_ttrp_d_n8"
                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN "as_of_date" IS NULL THEN 'n' ELSE 'v' || CAST("as_of_date" AS VARCHAR) END AS "_ttrp_d_n8"
                                        FROM "inventory") AS "t2"
                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN MAX("as_of_date") IS NULL THEN 'n' ELSE 'v' || CAST(MAX("as_of_date") AS VARCHAR) END AS "_ttrp_dm_n8"
                                        FROM "inventory"
                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t5" ON "t2"."_ttrp_g_n8_0" = "t5"."_ttrp_g_n8_0" AND "t2"."_ttrp_g_n8_1" = "t5"."_ttrp_g_n8_1" AND "t2"."_ttrp_d_n8" = "t5"."_ttrp_dm_n8") AS "t6" ON "t1"."item" = "t6"."item" AND "t1"."warehouse" = "t6"."warehouse") AS "t7"
                    LEFT JOIN (SELECT *
                        FROM "warehouse_outage"
                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t8" ON "t7"."warehouse" = "t8"."warehouse") AS "t9"
        WHERE "t9"."outage" OR "t9"."on_hand" < "t9"."quantity") AS "t11"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t40"."order_number", "t40"."customer", "t40"."channel", "t40"."fulfilling_warehouse", "t40"."value", "t40"."placed_date", "t40"."state", COALESCE("t40"."n_short", 0) AS "n_short", COALESCE("t40"."n_price", 0) AS "n_price", COALESCE("t46"."n_due", 0) AS "n_due"
                FROM (SELECT "t28"."order_number", "t28"."customer", "t28"."channel", "t28"."fulfilling_warehouse", "t28"."value", "t28"."placed_date", "t28"."state", "t28"."n_short", "t39"."n_price"
                        FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t27"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t13"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t22"."order_number", "t22"."customer", "t22"."channel", "t22"."fulfilling_warehouse", "t22"."value", "t22"."placed_date", "t22"."state", "t22"."line_no", "t22"."item", "t22"."quantity", "t22"."unit_price", "t22"."ext_sales_price", "t22"."warehouse", "t22"."sold_date", "t22"."customer0", "t22"."channel0", "t22"."as_of_date", "t22"."quantity_on_hand", "t22"."_ttrp_g_n8_0", "t22"."_ttrp_g_n8_1", "t22"."_ttrp_d_n8", "t23"."warehouse" AS "warehouse0", "t23"."from_date", "t23"."to_date", "t23"."reason", COALESCE("t22"."quantity_on_hand", 0) AS "on_hand", "t23"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t16"."order_number", "t16"."customer", "t16"."channel", "t16"."fulfilling_warehouse", "t16"."value", "t16"."placed_date", "t16"."state", "t16"."line_no", "t16"."item", "t16"."quantity", "t16"."unit_price", "t16"."ext_sales_price", "t16"."warehouse", "t16"."sold_date", "t16"."customer0", "t16"."channel0", "t21"."as_of_date", "t21"."quantity_on_hand", "t21"."_ttrp_g_n8_0", "t21"."_ttrp_g_n8_1", "t21"."_ttrp_d_n8"
                                                        FROM (SELECT "t15"."order_number", "t15"."customer", "t15"."channel", "t15"."fulfilling_warehouse", "t15"."value", "t15"."placed_date", "t15"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t15"
                                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t15"."order_number" = "sales_line0"."order_number") AS "t16"
                                                            LEFT JOIN (SELECT "t17"."as_of_date", "t17"."item", "t17"."warehouse", "t17"."quantity_on_hand", "t17"."_ttrp_g_n8_0", "t17"."_ttrp_g_n8_1", "t17"."_ttrp_d_n8"
                                                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN "as_of_date" IS NULL THEN 'n' ELSE 'v' || CAST("as_of_date" AS VARCHAR) END AS "_ttrp_d_n8"
                                                                        FROM "inventory") AS "t17"
                                                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN MAX("as_of_date") IS NULL THEN 'n' ELSE 'v' || CAST(MAX("as_of_date") AS VARCHAR) END AS "_ttrp_dm_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t20" ON "t17"."_ttrp_g_n8_0" = "t20"."_ttrp_g_n8_0" AND "t17"."_ttrp_g_n8_1" = "t20"."_ttrp_g_n8_1" AND "t17"."_ttrp_d_n8" = "t20"."_ttrp_dm_n8") AS "t21" ON "t16"."item" = "t21"."item" AND "t16"."warehouse" = "t21"."warehouse") AS "t22"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t23" ON "t22"."warehouse" = "t23"."warehouse") AS "t24"
                                        WHERE "t24"."outage" OR "t24"."on_hand" < "t24"."quantity"
                                        GROUP BY "order_number") AS "t27" ON "t13"."order_number" = "t27"."order_number") AS "t28"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t31"."order_number", "t31"."line_no", "t31"."item", "t31"."unit_price", "t31"."customer", "t31"."channel", "t31"."placed_date", "t35"."order_number" AS "order_number0", "t35"."line_no" AS "line_no0", "t35"."price"
                                        FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t30"."customer", "t30"."channel", "t30"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t30"
                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t30"."order_number" = "sales_line1"."order_number") AS "t31"
                                            INNER JOIN (SELECT "t34"."order_number", "t34"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t33"."customer", "t33"."channel", "t33"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t33"
                                                            INNER JOIN "sales_line" AS "sales_line2" ON "t33"."order_number" = "sales_line2"."order_number") AS "t34"
                                                    LEFT JOIN "customer_price" ON "t34"."item" = "customer_price"."item" AND "t34"."customer" = "customer_price"."customer" AND "t34"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t34"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t34"."item" = "price_list"."item" AND "t34"."channel" = "price_list"."channel" AND "t34"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t34"."placed_date" <= "price_list"."valid_to")) AS "t35" ON "t31"."order_number" = "t35"."order_number" AND "t31"."line_no" = "t35"."line_no") AS "t36"
                                WHERE "t36"."price" IS NULL OR ABS("t36"."unit_price" - "t36"."price") > :tolerance
                                GROUP BY "order_number0") AS "t39" ON "t28"."order_number" = "t39"."order_number") AS "t40"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t42"."order_number", "t42"."customer", "t42"."channel", "t42"."fulfilling_warehouse", "t42"."value", "t42"."placed_date", "t42"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t42"
                                    INNER JOIN "invoice" ON "t42"."customer" = "invoice"."customer") AS "t43"
                        WHERE "t43"."status" = 'open' AND "t43"."due" < :as_of
                        GROUP BY "order_number") AS "t46" ON "t40"."order_number" = "t46"."order_number") AS "t47"
        WHERE "t47"."n_short" > 0 OR "t47"."n_price" > 0
        GROUP BY "order_number") AS "t50" ON "t11"."order_number" = "t50"."order_number"
